        let cx = &mut gpui_kit::VisualTestContext::from_window(handle, cx);
        cx.simulate_mouse_move(center, None, gpui_kit::Modifiers::default());
        cx.run_until_parked();
        assert_eq!(bevel(cx), (2, 2, true), "no raised bevel on hover");

        cx.simulate_mouse_down(
