        );
        cx.simulate_mouse_move(
            gpui_kit::point(gpui_kit::px(10.), gpui_kit::px(300.)),
            None,
            gpui_kit::Modifiers::default(),
        );
        cx.run_until_parked();
        assert_eq!(bevel(cx), (0, 0, false), "the bevel stayed");
    }

